//! Deterministic multilingual rendering of structured claims, not unrestricted translation.
use crate::{indexed::Retrieved,evidence::{assess,Assessment}};
#[derive(Clone,Copy)]pub enum Language{English,French,Romanian}
pub fn render(r:&Retrieved,l:Language)->String{
 let header=match(l,assess(r)){(Language::English,Assessment::Missing)=>"No stored claim.",(Language::French,Assessment::Missing)=>"Aucune affirmation enregistrée.",(Language::Romanian,Assessment::Missing)=>"Nicio afirmație stocată.",(Language::English,Assessment::Incomplete)=>"Incomplete results; unverified claims:",(Language::French,Assessment::Incomplete)=>"Résultats incomplets ; affirmations non vérifiées :", (Language::Romanian,Assessment::Incomplete)=>"Rezultate incomplete; afirmații neverificate:",(Language::English,Assessment::MultipleValues)=>"Multiple stored values; unresolved:",(Language::French,Assessment::MultipleValues)=>"Plusieurs valeurs enregistrées ; non résolues :", (Language::Romanian,Assessment::MultipleValues)=>"Valori multiple stocate; nerezolvate:",(Language::English,_)=>"Unverified stored claim:",(Language::French,_)=>"Affirmation enregistrée non vérifiée :", (Language::Romanian,_)=>"Afirmație stocată neverificată:"};
 let mut out=header.to_owned();for f in &r.facts{let sentence=if f.relation.eq_ignore_ascii_case("capital"){match l{Language::English=>format!("{} is the capital of {}.",f.object,f.subject),Language::French=>format!("{} est la capitale de {}.",f.object,f.subject),Language::Romanian=>format!("{} este capitala {}.",f.object,f.subject)}}else{format!("{} | {} | {}",f.subject,f.relation,f.object)};out.push_str(&format!("\n{} [source: {:?}]",sentence,f.sources));}out
}
#[test]fn renders(){use crate::{indexed::Retrieved,store::parse_tsv};let r=Retrieved{facts:vec![parse_tsv("France\tcapital\tParis\tgeo\tsrc").unwrap()],bytes:0,truncated:false};assert!(render(&r,Language::French).contains("Paris est la capitale de France."));assert!(render(&r,Language::Romanian).contains("neverificată"));}
